package moe.tachyon.windwhisper.forum

import io.ktor.client.call.body
import io.ktor.client.request.forms.MultiPartFormDataContent
import io.ktor.client.request.forms.formData
import io.ktor.client.request.setBody
import io.ktor.client.statement.bodyAsText
import io.ktor.http.Headers
import io.ktor.http.HttpHeaders
import io.ktor.http.isSuccess
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.jsonPrimitive
import moe.tachyon.windwhisper.ai.GeneratedImageStore
import moe.tachyon.windwhisper.mainConfig

/** Upload only stored generated bytes; the forum's short URL is the attachment reference. */
suspend fun LoginData.uploadGeneratedImage(image: GeneratedImageStore.Image): String
{
    val response = post("${mainConfig.url}/uploads.json")
    {
        setBody(MultiPartFormDataContent(formData {
            append("type", "composer")
            append("synchronous", "true")
            append("file", image.bytes, Headers.build {
                append(HttpHeaders.ContentType, image.contentType)
                append(HttpHeaders.ContentDisposition, "filename=\"${image.filename}\"")
            })
        }))
    }
    require(response.status.isSuccess()) { "上传生成图片失败，HTTP 状态码 ${response.status.value}\n${response.bodyAsText()}" }
    val shortUrl = response.body<JsonObject>()["short_url"]?.jsonPrimitive?.content
    require(shortUrl != null && shortUrl.matches(Regex("upload://[A-Za-z0-9_-]+\\.(?:png|jpe?g|webp)", RegexOption.IGNORE_CASE))) {
        "论坛未返回有效的图片 short_url"
    }
    return "![生成图片]($shortUrl)"
}
